export function normalize(text){return String(text).toLocaleLowerCase('de').normalize('NFKC').replace(/ß/g,'ss').replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim();}
const index=new Map(Object.entries(FAQ).flatMap(([id,f])=>f.questions.map(q=>[normalize(q),id])));
export function classifyLocal(question){
  const q=normalize(question);
  if(!q)return {kind:'empty'};
  // An exact approved question is the only path to an immediate answer.
  if(index.has(q))return {kind:'answer',id:index.get(q)};
  if(/^(was kostet (das|es)|ist (das|es) (kostenlos|kostenfrei)|wie teuer ist (das|es)|kosten|preis)$/.test(q))return {kind:'clarify',ids:['kosten','versicherung']};
  if(/@|\b\d[\d\s+()-]{6,}\b/.test(question)||/\b(passwort ist|vertragsnummer|kontonummer|iban|diagnose|versichertennummer|schadennummer)\b/.test(q))return {kind:'private'};
  if(/\b(ignoriere|ignore|systemprompt|system prompt|garantiert|garantie|garantieren|versprich|schaden|schadensfall|deckt|gedeckt|kündigen|kuendigen|steuer|förderung|foerderung|diagnose|beitrag|prämie|praemie|provision|vergütung|verguetung)\b/.test(q))return {kind:'contact'};
  const words=new Set(q.split(' '));
  const ids=Object.entries(FAQ).filter(([,f])=>f.keywords.some(k=>words.has(normalize(k)))).map(([id])=>id).slice(0,3);
  return ids.length?{kind:'suggest',ids}:{kind:'contact'};
}

// Individual commitments and sensitive topics always go to a person, never to AI.
export function canUseAI(question){
 const q=normalize(question);
 return !['private','empty','clarify'].includes(classifyLocal(question).kind)&&!/\b(ignoriere|ignore|systemprompt|system prompt|garantiert|garantie|garantieren|versprich|schaden|schadensfall|deckt|gedeckt|kündigen|kuendigen|steuer|förderung|foerderung|beitrag|prämie|praemie|provision|vergütung|verguetung|gesundheit|krankheit)\b/.test(q);
}
